//! Startup metadata coordinator. Actual file work stays on the existing IoWorker.
use super::*;
use skylive_host::last_native_document::LastNativeDocument;
struct Pending{request:u64,session:u64,revision:u64,cancelled:bool}
struct Write{request:u64,last:LastNativeDocument}
struct Problem{summary:&'static str,detail:String}
#[derive(Default)]pub(super) struct Flow{
 enabled:bool,pending:Option<Pending>,deferred:Option<Intent>,retire:Option<crate::startup::Native>,retiring:Option<u64>,
 metadata_path:Option<PathBuf>,remembered:Option<LastNativeDocument>,desired:Option<LastNativeDocument>,write:Option<Write>,failed:Option<LastNativeDocument>,
 first_run:bool,close_after_write:bool,problems:Vec<Problem>,
}
impl StudioApp{
 pub(super) fn begin_startup(&mut self,ctx:&egui::Context){self.startup.enabled=true;let session=self.session.identity();let revision=self.session.snapshot().revision();match self.io.submit(session,Job::Startup){Ok(())=>match self.io.request(){Some(request)=>{self.startup.pending=Some(Pending{request,session,revision,cancelled:false});self.message(false,"Preparing startup settings and the last native document…");},None=>self.startup_problem("Startup preparation failed","The I/O request has no identity.")},Err(error)=>self.startup_problem("Startup preparation failed",error)}ctx.request_repaint();}
 pub(super) fn cancel_startup(&mut self){if let Some(pending)=&mut self.startup.pending{pending.cancelled=true;}self.startup.deferred=None;self.startup.first_run=false;}
 /// A later explicit document workflow wins. One latest bounded intent waits for
 /// the already-admitted filesystem read to return; it is not a false cancel ack.
 pub(super) fn defer_startup_intent(&mut self,intent:Intent,ctx:&egui::Context)->Option<Intent>{
  if matches!(&intent,Intent::Exit){self.cancel_startup();return Some(intent);}
  if self.startup.pending.is_none()&&self.startup.retiring.is_none()&&self.startup.retire.is_none(){return Some(intent);}
  if !matches!(&intent,Intent::OpenDocumentPicker(_)|Intent::NewCollection|Intent::Load|Intent::Recover|Intent::ImportObs {..}|Intent::OpenSetup|Intent::CollectionLibrary(crate::views::collection_library::Action::Create{..}|crate::views::collection_library::Action::Remove|crate::views::collection_library::Action::Switch{..})){return Some(intent);}
  if let Intent::ImportObs{path}=&intent{if path.chars().count()>4096{self.startup_problem("Startup document choice was rejected","The requested path exceeds 4096 characters.");return None;}}
  self.cancel_startup();self.startup.deferred=Some(intent);self.message(false,"The newer document choice will run after startup I/O retires.");ctx.request_repaint();None
 }
 fn startup_problem(&mut self,summary:&'static str,detail:impl ToString){let detail=detail.to_string();eprintln!("{summary}: {detail}");if self.startup.problems.len()==8{self.startup.problems.remove(0);}let shown=detail.chars().take(4096).collect();self.startup.problems.push(Problem{summary,detail:shown});self.message(true,summary);}
 pub(super) fn startup_completion(&mut self,completion:crate::io::Completion,ctx:&egui::Context)->Option<crate::io::Completion>{
  if self.startup.retiring==Some(completion.request){self.startup.retiring=None;if !matches!(completion.result,Ok(Reply::StartupRetired)){self.startup_problem("Startup cleanup reported a problem","The metadata retirement acknowledgement was unavailable.");}ctx.request_repaint();return None;}
  if self.startup.write.as_ref().is_some_and(|write|write.request==completion.request){let pending=self.startup.write.take()?;match completion.result{Ok(Reply::NativeRemembered(last))if last==pending.last=>{self.startup.remembered=Some(last);self.startup.failed=None;},Err(error)=>{self.startup.failed=Some(pending.last);self.startup_problem("The last native document could not be remembered",error);},_=>{self.startup.failed=Some(pending.last);self.startup_problem("The last native document could not be remembered","The I/O owner returned an unexpected receipt.");}}if self.startup.close_after_write{self.startup.close_after_write=false;if self.startup.failed.is_some(){self.close_dialog=true;}else{self.shutdown(ctx);}}ctx.request_repaint();return None;}
  if !self.startup.pending.as_ref().is_some_and(|pending|pending.request==completion.request){return Some(completion);}
  let pending=self.startup.pending.take()?;let fresh=completion.session==pending.session&&self.session.identity()==pending.session&&self.session.snapshot().revision()==pending.revision&&!self.session.is_closed();
  let(mut loaded,mut repair_native)=match completion.result{Ok(Reply::StartupLoaded(value))=>(value,None),Ok(Reply::StartupRepairLoaded{settings,native})=>(settings,native),Err(error)=>{self.startup_problem("Startup preparation failed",error);return None;},_=>{self.startup_problem("Startup preparation failed","The I/O owner returned an unexpected startup receipt.");return None;}};
  // Storage-location metadata is not document publication. Preserve it even if
  // the untouched initial document no longer accepts this prepared candidate.
  self.preferences_path=loaded.preferences_path.take();self.startup.metadata_path=loaded.metadata_path.take();
  match loaded.remembered{Ok(last)=>self.startup.remembered=last,Err(error)=>self.startup_problem("Remembered document metadata could not be read",error)}
  if !fresh{if let Some(Ok(event))=repair_native.take(){self.begin_document_repair(event,true,false,ctx);}if let Some(Ok(native))=loaded.native.take(){self.startup.retire=Some(native);}self.startup.first_run=false;self.startup_problem("Startup result was obsolete","The current document and preferences were retained.");ctx.request_repaint();return None;}
  let mut preferences_ok=true;let missing=matches!(&loaded.preferences,Ok(None));match loaded.preferences{Ok(Some(preferences))=>{if let Err(error)=self.session.apply(Command::SetUserPreferences{preferences}){preferences_ok=false;self.startup_problem("Installed preferences could not be applied",error);}},Ok(None)=>{},Err(error)=>{preferences_ok=false;self.startup_problem("Installed preferences could not be read",error)}}
  self.saved_preferences=self.session.snapshot().preferences().clone();if preferences_ok{self.arm_startup_process_priority();}
  if loaded.localization.language()==self.session.snapshot().preferences().language(){self.localization_path=loaded.localization_path;self.localization=loaded.localization;crate::i18n::install(ctx,self.localization.clone(),&self.localization_path);if let Some(error)=loaded.localization_error{self.startup_problem("External localization is unavailable; embedded translations are in use",error);}}
  let can_reopen=!pending.cancelled&&!self.recording.active()&&!self.streaming.active()&&!self.replay.active()&&!self.ndi_output.owner.any_active()&&!self.virtual_camera.owned()&&!self.document_repair.owns()&&self.dialog.is_none()&&!self.documents.modal_open()&&!self.setup.is_open()&&!self.close_dialog&&!self.allow_close;
  self.startup.first_run=missing&&!pending.cancelled;
  if let Some(native)=repair_native.take(){match native{Ok(event)=>self.begin_document_repair(event,true,can_reopen,ctx),Err(error)=>self.startup_problem("The last native document could not be reopened",error)}}
  if can_reopen{match loaded.native.take(){Some(Ok(native))=>{if let Some(native)=self.accept_startup_document(native,ctx){self.startup.retire=Some(native);self.startup_problem("Startup result was obsolete","The current document was retained instead of prompting to discard it.");}},Some(Err(error))=>self.startup_problem("The last native document could not be reopened",error),None=>{}}}else if let Some(Ok(native))=loaded.native.take(){self.startup.retire=Some(native);}
  if self.startup.deferred.is_none(){self.refresh_library_after_publication(ctx);}
  ctx.request_repaint();None
 }
 pub(super) fn update_startup(&mut self,ctx:&egui::Context){
  if self.allow_close||self.session.is_closed()||self.document_repair.owns()||self.startup.pending.is_some()||self.startup.retiring.is_some(){return;}
  if let Some(native)=self.startup.retire.take(){if self.io.busy(){self.startup.retire=Some(native);return;}match self.io.submit(self.session.identity(),Job::RetireStartupNative(native)){Ok(())=>self.startup.retiring=self.io.request(),Err(error)=>self.startup_problem("Startup cleanup reported a problem",error)}ctx.request_repaint();return;}
  if self.io.busy()||self.close_dialog{return;}
  if let Some(intent)=self.startup.deferred.take(){self.intent(intent,ctx);return;}
  if self.startup.first_run&&!self.setup.is_open()&&self.dialog.is_none()&&!self.documents.modal_open(){self.startup.first_run=false;if self.session.snapshot().preferences().setup_state().is_unseen(){self.open_setup(views::setup::SetupOrigin::FirstRun);}}
 }
 pub(super) fn remember_native_document(&mut self,path:PathBuf){if !self.startup.enabled{return;}match LastNativeDocument::new(path){Ok(last)=>{self.startup.desired=Some(last);self.startup.failed=None;},Err(error)=>self.startup_problem("The last native document could not be remembered",error)}}
 pub(super) fn persist_last_native_document(&mut self){if self.io.busy()||self.startup.pending.is_some()||self.documents.modal_open()||self.startup.write.is_some(){return;}let Some(last)=self.startup.desired.clone()else{return;};if self.startup.remembered.as_ref()==Some(&last)||self.startup.failed.as_ref()==Some(&last){return;}let Some(path)=self.startup.metadata_path.clone()else{self.startup.failed=Some(last);self.startup_problem("The last native document could not be remembered","The installed startup metadata location is unavailable.");return;};match self.io.submit(self.session.identity(),Job::RememberNative{path,last:last.clone()}){Ok(())=>{if let Some(request)=self.io.request(){self.startup.write=Some(Write{request,last});}},Err(error)=>{self.startup.failed=Some(last);self.startup_problem("The last native document could not be remembered",error);}}}
 pub(super) fn wait_last_native_document_before_close(&mut self,ctx:&egui::Context)->bool{let needs=self.startup.desired.as_ref().is_some_and(|desired|self.startup.remembered.as_ref()!=Some(desired)&&self.startup.failed.as_ref()!=Some(desired));if self.startup.write.is_none()&&!needs{return false;}self.startup.close_after_write=true;self.persist_last_native_document();if self.startup.write.is_none()&&!self.io.busy(){self.startup.close_after_write=false;if self.startup.failed.is_some(){self.close_dialog=true;ctx.request_repaint();return true;}return false;}ctx.request_repaint_after(std::time::Duration::from_millis(32));true}
 pub(super) fn cancel_startup_close(&mut self){self.startup.close_after_write=false;}
 pub(super) fn show_startup_information(&mut self,ctx:&egui::Context){if self.startup.pending.is_none()&&self.startup.problems.is_empty(){return;}let mut empty=false;let mut open=false;let mut dismiss=false;egui::TopBottomPanel::top("startup-document-information").max_height(160.0).show(ctx,|ui|{ui.style_mut().wrap_mode=Some(egui::TextWrapMode::Wrap);if let Some(pending)=&self.startup.pending{ui.horizontal_wrapped(|ui|{ui.spinner();ui.label(crate::i18n::tr(ui,if pending.cancelled{"Waiting for startup I/O to retire…"}else{"Preparing startup settings and the last native document…"}));if ui.button(crate::i18n::tr(ui,"Use an empty collection")).on_hover_text(crate::i18n::tr(ui,"Keep the saved file unchanged and use a new collection after startup I/O returns.")).clicked(){empty=true;}if ui.button(crate::i18n::tr(ui,"Open another collection…")).on_hover_text(crate::i18n::tr(ui,"Choose a different native document after startup I/O returns.")).clicked(){open=true;}});}if !self.startup.problems.is_empty(){egui::CollapsingHeader::new(crate::i18n::tr(ui,"Startup information")).default_open(true).show(ui,|ui|{egui::ScrollArea::vertical().id_salt("startup-problems").max_height(88.0).show(ui,|ui|{for problem in &self.startup.problems{ui.colored_label(ui.visuals().warn_fg_color,crate::i18n::tr(ui,problem.summary));ui.label(crate::i18n::tr(ui,&problem.detail));}});if ui.button(crate::i18n::tr(ui,"Dismiss startup information")).clicked(){dismiss=true;}});}});if dismiss{self.startup.problems.clear();}if open{self.intent(Intent::OpenDocumentPicker(views::document_picker::DocumentAction::Open),ctx);}else if empty{self.intent(Intent::NewCollection,ctx);}}
}
